'use strict';
/**
 * Patch only the ephemeral Android project generated by expo prebuild.
 * Fail closed if the Expo/React Native Gradle template changes.
 * The private keystore and passwords never belong in source control.
 */
const fs=require('node:fs');

function configurePlaySigning(text){
  if(typeof text!=='string'||!text.includes('android {'))throw Error('Android Gradle file not recognized.');
  const buildIndex=text.indexOf('buildTypes {');
  if(buildIndex<0)throw Error('Missing buildTypes configuration.');
  const releaseMatch=/\brelease\s*\{/.exec(text.slice(buildIndex));
  if(!releaseMatch)throw Error('Missing release build type.');
  const releaseIndex=buildIndex+releaseMatch.index;
  const debugSigning='signingConfig signingConfigs.debug';
  const signIndex=text.indexOf(debugSigning,releaseIndex);
  if(signIndex<0||signIndex-releaseIndex>1200)throw Error('Release signing template is not recognized; no changes made.');
  if(text.includes('signingConfigs.jynloPlayUpload'))throw Error('Play signing has already been configured.');
  const snippet=`
    signingConfigs {
        jynloPlayUpload {
            storeFile file(System.getenv('JYNLO_PLAY_UPLOAD_KEYSTORE_PATH'))
            storePassword System.getenv('JYNLO_PLAY_UPLOAD_STORE_PASSWORD')
            keyAlias System.getenv('JYNLO_PLAY_UPLOAD_KEY_ALIAS')
            keyPassword System.getenv('JYNLO_PLAY_UPLOAD_KEY_PASSWORD')
        }
    }
`;
  return text.slice(0,buildIndex)+snippet+text.slice(buildIndex,signIndex)+
    'signingConfig signingConfigs.jynloPlayUpload'+text.slice(signIndex+debugSigning.length);
}
if(require.main===module){
  const file=process.argv[2];
  if(!file||!file.endsWith('android/app/build.gradle'))throw Error('Pass the generated android/app/build.gradle path.');
  const source=fs.readFileSync(file,'utf8');
  const next=configurePlaySigning(source);
  fs.writeFileSync(file,next,'utf8');
  console.log('Release build configured for private Jynlo upload keystore.');
}
module.exports={configurePlaySigning};
